    """Compact list of .py files under src2/ (and tests/), gitignored excluded.

    Replaces the whole-repo ``get_repo_structure`` dump, which flooded the
    planner brief with _docs/, _prd/, .beads/, WEB/, logs/ and audit noise.
    Rules (per user directive):
      1. walk starts from src2/ (and tests/),
      2. .py files only,
      3. drop any path matched by .gitignore (so .beads/, logs/, _prd/,
         training_data *.json, etc. never appear).
    """
    candidates = _collect_py_candidates()
    if not candidates:
        return "(no .py sources found under src2/ or tests/)"
    shown = _filter_ignored(candidates)
    if not shown:
        return "(no tracked .py sources found under src2/ or tests/)"
    return _render_tree_lines(shown)


def _collect_py_candidates() -> list[str]:
    """Walk src2/ and tests/ and collect all .py file paths relative to REPO_ROOT."""
    import subprocess

    roots = [REPO_ROOT / "src2", REPO_ROOT / "tests"]
    candidates: list[str] = []
    for root in roots:
        if not root.is_dir():
            continue
        candidates.extend(_collect_from_root(root))
    return candidates


def _collect_from_root(root: Path) -> list[str]:
    """Collect .py file paths relative to REPO_ROOT from a single root directory."""
    results: list[str] = []
    for path in sorted(root.rglob("*.py")):
        rel = _relative_to_repo_root(path)
        if rel is not None:
            results.append(rel)
    return results


def _relative_to_repo_root(path: Path) -> str | None:
    """Return path relative to REPO_ROOT, or None if not under repo root."""
    try:
        return str(path.relative_to(REPO_ROOT))
    except ValueError:
        return None


def _filter_ignored(candidates: list[str]) -> list[str]:
    """Remove gitignored paths from candidates using a single git check-ignore call."""
    try:
        proc = subprocess.run(
            ["git", "check-ignore", "--stdin", "--no-index"],
            input="\n".join(candidates),
            capture_output=True,
            text=True,
            cwd=str(REPO_ROOT),
            timeout=30,
        )
        ignored = set(proc.stdout.splitlines())
        return [c for c in candidates if c not in ignored]
    except (subprocess.SubprocessError, OSError):
        return candidates


def _render_tree_lines(shown: list[str]) -> str:
    """Render a list of relative paths as an indented tree."""
    tree_lines: list[str] = []
    for rel in shown:
        parts = rel.split("/")
        indent = "    " * (len(parts) - 1)
        tree_lines.append(f"{indent}└── {parts[-1]}")
    return "\n".join(tree_lines)"}
